      "dis-beyazlatma": { title: "Diş Beyazlatma", subtitle: "Teeth Whitening", emoji: "🪥", description: "Pendik ve Haliç Panorama Dental'de diş beyazlatma tedavisi, uluslararası sertifikalı diş hekimimiz tarafından uygulanmaktadır. Kullandığımız ürünler FDA ve CE belgeli, klinik olarak test edilmiş profesyonel beyazlatma sistemleridir.", benefits: ["1 seansta 8 ton açılma", "Diş minesine zarar vermez", "Anında görünür sonuç", "Uzun ömürlü etki", "Ağrısız prosedür", "FDA onaylı ürünler"], steps: [{ step: "1", title: "Diş Yüzeyi Temizliği", desc: "Tartar ve plak temizliği ile beyazlatma öncesi hazırlık." }, { step: "2", title: "Diş Eti Koruması", desc: "Jel ve ışık bariyeri ile diş etleri korunur." }, { step: "3", title: "Beyazlatma Jeli & Laser", desc: "Aktif karbojen peroksit jeli uygulanır, laser ile aktive edilir." }, { step: "4", title: "Koruyucu Flor", desc: "Seans sonunda dişlere güçlendirici flor uygulanır." }] },
      "zirkonyum-kaplama": { title: "Zirkonyum Kaplama", subtitle: "Zirconia Crown", emoji: "💎", description: "Zirkonyum kaplamalar, dental teknolojisinin son 20 yılda geçirdiği inanılmaz dönüşümün en çarpıcı örneğidir. Bugün üç farklı ana kategoride üretilmektedir:\n\n• Monolitik Zirkonyum: Tek parça, yüksek dayanımlı ve tamamen metal içermeyen yapı.\n• Monolitik Çift Katmanlı Zirkonyum: Alt yapı yüksek dayanımlı zirkon, üst yüzey ince porselen tabakasıyla kaplı estetik versiyon.\n• Metal-Seramik: Geleneksel yöntem.", benefits: ["Metal içermez", "Işık geçirgen doğal görünüm", "Alerjik reaksiyon riski sıfır", "Yüksek kırılma direnci", "15+ yıl ömür", "Tam renk uyumu"], steps: [{ step: "1", title: "Diş Hazırlığı", desc: "Minimum diş kesimi ile mükemmel altyapı hazırlanır." }, { step: "2", title: "Ölçü & Tasarım", desc: "Dijital ağız ölçüsü alınır, CAD/CAM sistemiyle tasarlanır." }, { step: "3", title: "Geçici Kaplama", desc: "Laboratuvar süreci boyunca geçici estetik kaplama takılır." }, { step: "4", title: "Kalıcı Yapıştırma", desc: "Zirkonyum kronlar hassas adeziv ile kalıcı olarak yapıştırılır." }] },
      "kemik-grefti": { title: "Kemik Grefti", subtitle: "Bone Graft", emoji: "🦴", description: "Kemik grefti, diş kaybının ardından oluşan kemik erimesini durdurmak ve implant uygulaması için gerekli kemik hacmini yeniden oluşturmak amacıyla kullanılan ileri bir cerrahi prosedürdür.", benefits: ["İmplant öncesi zemin hazırlar", "Kemik erimesini durdurur", "Yüz konturlarını korur", "Başarı oranı %95+", "Minimal invazif teknikler", "Sinus lifting seçeneği"], steps: [{ step: "1", title: "Kemik Analizi", desc: "3D CBCT tomografi ile kemik yoğunluğu ve hacmi ölçülür." }, { step: "2", title: "Greft Materyali Seçimi", desc: "Otolog, allograft veya sentetik greft materyali planlanır." }, { step: "3", title: "Cerrahi Uygulama", desc: "Lokal anestezi altında kemik grefti yerleştirilir." }, { step: "4", title: "İyileşme & İmplant", desc: "3–6 ay iyileşme sonrası implant uygulamasına geçilir." }] },
      "dis-teli-ortodonti": { title: "Diş Plak Tedavisi & Ortodonti", subtitle: "Orthodontics", emoji: "😁", description: "Şeffaf plak (clear aligner) tedavisi, geleneksel diş telinin yerini alan ve dünya genelinde milyonlarca hasta tarafından tercih edilen çağdaş bir ortodonti sistemidir.", benefits: ["Şeffaf plak seçeneği", "Görünmez tel teknolojisi", "Her yaşa uygun", "Ağız sağlığını iyileştirir", "Kalıcı sonuçlar", "Dijital simülasyon"], steps: [{ step: "1", title: "Ortodontik Muayene", desc: "Diş modeli, röntgen ve fotoğraf analizi ile kapsamlı değerlendirme." }, { step: "2", title: "Tedavi Planı", desc: "Kişiselleştirilmiş ortodontik tedavi planı ve süre tahmini." }, { step: "3", title: "Aparey Uygulaması", desc: "Seçilen sistem (şeffaf plak, metal veya seramik tel) takılır." }, { step: "4", title: "Retansiyon", desc: "Tedavi sonrası pekiştirici plak ile kalıcı sonuç korunur." }] },
